import json
import numpy as np

# Build an analytic SOP circuit: layer 0 forms its eight product terms;
# layer 1 ORs them using ReLU(s)-ReLU(s-1); later layers preserve signals.
shapes = {
    "w0": (34, 10), "w1": (34, 34), "w2": (34, 34), "w3": (34, 34),
    "b0": (34,), "b1": (34,), "b2": (34,), "b3": (34,),
    "out": (3, 34), "bias": (3,),
}
weights = {k: np.zeros(v, dtype=np.float32) for k, v in shapes.items()}

# Retain the ten input bits through every hidden layer.
for layer in ("w0", "w1"):
    for i in range(10):
        weights[layer][i, i] = 1.0
for layer in ("w2", "w3"):
    for i in range(34):
        weights[layer][i, i] = 1.0

# SOP from the public truth-table minimization. Each term is a conjunction
# of literals, implemented as ReLU(sum(literals) - n + 1).
terms = [
    ([(6, 1), (7, 1), (8, 1)], []),
    ([(2, 1), (4, 1), (6, 1), (8, 1)], []),
    ([(0, 1), (6, 1), (7, 1)], [2]),
    ([(2, 1), (6, 1), (7, 1)], [0]),
    ([(0, 1), (2, 1), (4, 1), (6, 1)], [7]),
    ([(6, 1)], [2, 4, 7]),
    ([(6, 1)], [0, 2, 7, 8]),
    ([(0, 1), (4, 1), (8, 1)], [1, 6, 9]),
]
for t, (positive, negative) in enumerate(terms):
    row = 10 + 3 * t
    for i, _ in positive:
        weights["w0"][row, i] = 1.0
    for i in negative:
        weights["w0"][row, i] = -1.0
    n = len(positive) + len(negative)
    weights["b0"][row] = len(negative) - n + 1

# OR of the eight product terms, encoded in triple 10..12:
# ReLU(sum terms) - ReLU(sum terms - 1) is exactly the Boolean OR.
for t in range(8):
    weights["w1"][10, 10 + 3 * t] = 1.0
    weights["w1"][12, 10 + 3 * t] = 1.0
weights["b1"][12] = -1.0

# Class 1 wins exactly when the signal encoded by h[10]+h[11]-h[12] is true.
weights["out"][1, 10] = 1.0
weights["out"][1, 12] = -1.0
weights["bias"][2] = -1.0

sub = {"patch": [
    {"op": "replace", "tensor": name, "values": arr.tolist()}
    for name, arr in weights.items()
]}
check_submission(sub)
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
